@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class AffiliatePayoutsTest {
 private PricingFixture f;private AffiliatePayouts service;private AffiliateBankSecrets secrets;private AffiliateCommissions commissions;private TransactionTemplate tx;private ActorAssertion.Actor finance;private final MutableClock clock=new MutableClock();
 static final class MutableClock extends Clock {Instant value=Instant.parse("2026-11-20T00:00:00Z");public java.time.ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId zone){return this;}public Instant instant(){return value;}}
 @BeforeAll void setup(){String url=System.getenv("NIGSON_TEST_JDBC_URL");Assumptions.assumeTrue(url!=null);var jdbc=new JdbcTemplate(new DriverManagerDataSource(url+"?currentSchema=commerce","nigson_commerce_app","mock-commerce-runtime"));var manager=new DataSourceTransactionManager(jdbc.getDataSource());f=new PricingFixture(jdbc,manager);var commands=new PlatformStore(jdbc,manager,clock,f.metrics);var audit=new AuditWriter(jdbc,clock,f.metrics);var links=new AffiliateLinks(jdbc,new com.nigson.commerce.pricing.PricingAuthority(jdbc,clock,3,"SYNTHETIC_DISTRIBUTOR_BUY"),commands,audit,clock,manager);commissions=new AffiliateCommissions(jdbc,audit,clock,3,manager);var cipher=new PaymentPayloadCipher("synthetic",Map.of("synthetic",new byte[32]));secrets=new AffiliateBankSecrets(()->cipher,"MOCK");service=new AffiliatePayouts(jdbc,links,commissions,secrets,commands,audit,manager,clock);finance=new ActorAssertion.Actor(f.finance.party(),f.finance.identityIssuer(),f.finance.identitySubject(),null,Set.of("FINANCE"),Set.of(),null);tx=new TransactionTemplate(manager);UUID org=UUID.randomUUID();f.organizations.add(org);jdbc.update("INSERT INTO commerce.organization(id,created_by,updated_by,name,country_code,status) VALUES (?,'test','test','Synthetic payout affiliate','NG','ACTIVE')",org);jdbc.update("INSERT INTO commerce.organization_membership(id,created_by,updated_by,organization_id,party_id,role,status) VALUES (?,'test','test',?,?,'OWNER','ACTIVE')",UUID.randomUUID(),org,f.customer.party());jdbc.update("INSERT INTO commerce.account_entitlement(id,created_by,updated_by,organization_id,entitlement,status,partner_type,source_application_id,approval_command_id,activated_at) VALUES (?,'test','test',?,'AFFILIATE_MARKETING','ACTIVE','AFFILIATE',?,?,now())",UUID.randomUUID(),org,UUID.randomUUID(),UUID.randomUUID());}
 @BeforeEach void reset(){clock.value=Instant.parse("2026-11-20T00:00:00Z");}
 @AfterAll void close(){if(f!=null)f.close();}
 private void rollback(Runnable test){tx.executeWithoutResult(s->{s.setRollbackOnly();test.run();});}
 private tools.jackson.databind.node.ObjectNode bankInput(UUID previous,String number){var body=EventCodec.JSON.createObjectNode();if(previous==null)body.putNull("expectedBankId");else body.put("expectedBankId",previous.toString());body.put("bankName","Synthetic Bank");body.put("accountName","Synthetic Affiliate");body.put("accountNumber",number);return body;}
 private String key(){return UUID.randomUUID().toString();}
 private UUID correlation(){return UUID.randomUUID();}
 private AffiliatePayouts.Bank approved(){var saved=service.saveBank(f.customer,bankInput(null,"0123456789"),key(),correlation());var bank=saved.bank();service.review(finance,f.customer.party(),EventCodec.JSON.valueToTree(Map.of("bankId",bank.id(),"version",bank.version(),"decision","APPROVED","reason","Synthetic bank review")),key(),correlation());return service.own(f.customer,0).bank();}
 private record Credit(UUID order,UUID entry,UUID attempt,UUID line,BigDecimal basis){}
 private Credit credit(String amount){BigDecimal commission=new BigDecimal(amount),basis=commission.divide(new BigDecimal("0.05"),2,RoundingMode.UNNECESSARY);UUID order=UUID.randomUUID(),entry=UUID.randomUUID(),attempt=UUID.randomUUID(),line=UUID.randomUUID();f.jdbc.update("INSERT INTO commerce.sales_order(id,created_by,updated_by,order_number,party_id,market_id,status,payment_status,fulfillment_status,currency_code,subtotal,discount_total,tax_total,delivery_total,grand_total,address_snapshot,commercial_snapshot,carrier_quote_id,carrier_snapshot) VALUES (?,'test','test',?, ?,?,'DELIVERED','PAID','DELIVERED','NGN',?,0,0,0,?,'{}','{}',?,'{}')",order,"SYN_"+order.toString().replace("-",""),f.finance.party(),f.market,basis,basis,f.carrier);f.jdbc.update("INSERT INTO commerce.order_line(id,created_by,order_id,sku_id,sku_code,product_name,unit,quantity,unit_amount,discount_amount,tax_amount,line_total,price_book_revision) VALUES (?,'test',?,?,'SYNTHETIC','Synthetic payout order','EA',1,?,0,0,?,0)",line,order,f.sku,basis,basis);f.jdbc.update("INSERT INTO commerce.payment_attempt(id,created_by,updated_by,order_id,provider,reference,merchant_account,expected_amount,currency_code,state,verified_at) VALUES (?,'test','test',?,'PAYSTACK',?,'synthetic',?,'NGN','SUCCEEDED',now())",attempt,order,"synthetic-"+attempt,basis);f.jdbc.update("INSERT INTO commerce.payment_transaction(id,created_by,attempt_id,provider_transaction_id,settled_amount,currency_code,provider_status,settled_at,verification_hash) VALUES (?,'test',?,?,?,'NGN','success',now(),?)",UUID.randomUUID(),attempt,"synthetic-"+attempt,basis,"1".repeat(64));f.jdbc.update("INSERT INTO commerce.shipment(id,created_by,updated_by,order_id,status,delivered_at) VALUES (?,'test','test',?,'DELIVERED',?)",UUID.randomUUID(),order,java.sql.Timestamp.from(clock.instant().minus(Duration.ofDays(8))));f.jdbc.update("INSERT INTO commerce.affiliate_commission_entry(id,created_by,party_id,order_id,kind,amount,merchandise_basis,rate,business_key) VALUES (?,'test',?,?,'EARN',?,?,0.05,?)",entry,f.customer.party(),order,commission,basis,"synthetic-"+entry);return new Credit(order,entry,attempt,line,basis);}
 private tools.jackson.databind.JsonNode resolved(AffiliatePayouts.Payout payout,boolean paid,String value){return EventCodec.JSON.valueToTree(paid?Map.of("version",payout.version(),"transferReference",value,"confirmTransferred",true):Map.of("version",payout.version(),"reason",value,"confirmNoTransfer",true));}
 private void rejectedSql(String sql,String expected){var nested=new TransactionTemplate(f.manager);nested.setPropagationBehavior(org.springframework.transaction.TransactionDefinition.PROPAGATION_NESTED);assertThatThrownBy(()->nested.executeWithoutResult(s->f.jdbc.execute(sql))).isInstanceOfSatisfying(org.springframework.dao.DataAccessException.class,failure->assertThat(failure.getMostSpecificCause().getMessage()).startsWith("ERROR: "+expected));}
 @Test void publicBankIdIsNotAReplayKeyForGuessingMaskedAccountDetails(){rollback(()->{String command=key();var first=service.saveBank(f.customer,bankInput(null,"0123456789"),command,correlation());assertThat(first.bank().id().toString()).isNotEqualTo(command);assertThatThrownBy(()->service.saveBank(f.customer,bankInput(null,"0123456789"),first.bank().id().toString(),correlation())).hasMessage("VERSION_MISMATCH");assertThatThrownBy(()->service.saveBank(f.customer,bankInput(null,"9999999999"),first.bank().id().toString(),correlation())).hasMessage("VERSION_MISMATCH");assertThat(service.saveBank(f.customer,bankInput(null,"0123456789"),command,correlation()).bank().id()).isEqualTo(first.bank().id());});}
 @Test void oldPrepareRetryAfterCommandExpiryAndMonthChangeReturnsOriginalPayout(){rollback(()->{var bank=approved();credit("45.00");String command=key();var body=EventCodec.JSON.valueToTree(Map.of("bankId",bank.id()));var original=service.prepare(finance,f.customer.party(),body,command,correlation());assertThat(original.id().toString()).isEqualTo(command);service.resolve(finance,original.id(),true,resolved(original,true,"SYNTHETIC_OLD_REPLAY"),key(),correlation());f.jdbc.update("DELETE FROM commerce.idempotency_record WHERE resource_id=? AND operation='API-231'",original.id());clock.value=Instant.parse("2026-12-20T00:00:00Z");credit("30.00");var replay=service.prepare(finance,f.customer.party(),body,command,correlation());assertThat(replay.id()).isEqualTo(original.id());assertThat(replay.state()).isEqualTo("PAID");assertThat(service.own(f.customer,0).balance().reserved()).isEqualTo("0.00");assertThat(service.own(f.customer,0).balance().available()).isEqualTo("30.00");assertThat(service.own(f.customer,0).payouts()).hasSize(1);});}
 @Test void financialSnapshotsAndPopulatedRollbackAreProtected()throws Exception {String rollback;try(var stream=getClass().getResourceAsStream("/db/changelog/054-bp3-affiliate-financial-guards-rollback.sql")){rollback=new String(stream.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);}rollback(()->{var bank=approved();credit("45.00");var payout=service.prepare(finance,f.customer.party(),EventCodec.JSON.valueToTree(Map.of("bankId",bank.id())),key(),correlation());rejectedSql("UPDATE commerce.affiliate_payout SET amount=1 WHERE id='"+payout.id()+"'","Affiliate payout financial snapshot is immutable");rejectedSql("DELETE FROM commerce.affiliate_payout WHERE id='"+payout.id()+"'","Affiliate payout history is immutable");rejectedSql("UPDATE commerce.affiliate_bank_detail SET content_hash='"+"0".repeat(64)+"' WHERE id='"+bank.id()+"'","Affiliate bank details are immutable");rejectedSql(rollback,"Affiliate financial records exist: use expand/contract migration");var admin=f.marketFixture.adminActor;var normalAdmin=new ActorAssertion.Actor(admin.party(),admin.identityIssuer(),admin.identitySubject(),null,Set.of("ADMIN"),Set.of(),null);assertThat(service.detail(normalAdmin,f.customer.party(),0,correlation()).bank().accountNumber()).isEqualTo("0123456789");});}
 @Test void concurrentPreparationsReserveOnlyOnePayout()throws Exception {
  UUID bank=tx.execute(s->{credit("45.00");return approved().id();});var pool=java.util.concurrent.Executors.newFixedThreadPool(2);var ready=new java.util.concurrent.CountDownLatch(2);var start=new java.util.concurrent.CountDownLatch(1);
  try{var tasks=new ArrayList<java.util.concurrent.Future<Object>>();for(int i=0;i<2;i++)tasks.add(pool.submit(()->{ready.countDown();if(!start.await(5,java.util.concurrent.TimeUnit.SECONDS))throw new IllegalStateException("START_TIMEOUT");try{return service.prepare(finance,f.customer.party(),EventCodec.JSON.valueToTree(Map.of("bankId",bank)),key(),correlation());}catch(com.nigson.shared.problem.Problem.Failure failure){return failure.getMessage();}}));assertThat(ready.await(5,java.util.concurrent.TimeUnit.SECONDS)).isTrue();start.countDown();var results=new ArrayList<Object>();for(var task:tasks)results.add(task.get(15,java.util.concurrent.TimeUnit.SECONDS));assertThat(results.stream().filter(AffiliatePayouts.Payout.class::isInstance).count()).isEqualTo(1);for(var result:results)if(result instanceof String failure)assertThat(failure).isIn("CONFLICT","IDEMPOTENCY_IN_PROGRESS");assertThat(service.own(f.customer,0).balance().reserved()).isEqualTo("45.00");assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.affiliate_payout WHERE party_id=?",Integer.class,f.customer.party())).isEqualTo(1);
  }finally{pool.shutdownNow();pool.awaitTermination(10,java.util.concurrent.TimeUnit.SECONDS);new TransactionTemplate(new DataSourceTransactionManager(f.admin.getDataSource())).executeWithoutResult(s->{f.admin.execute("ALTER TABLE commerce.affiliate_payout DISABLE TRIGGER USER");f.admin.execute("ALTER TABLE commerce.affiliate_bank_detail DISABLE TRIGGER USER");try{f.admin.update("DELETE FROM commerce.affiliate_payout WHERE party_id=?",f.customer.party());f.admin.update("DELETE FROM commerce.affiliate_commission_entry WHERE party_id=?",f.customer.party());f.admin.update("DELETE FROM commerce.shipment WHERE order_id IN(SELECT id FROM commerce.sales_order WHERE market_id=?)",f.market);f.admin.update("DELETE FROM commerce.order_line WHERE order_id IN(SELECT id FROM commerce.sales_order WHERE market_id=?)",f.market);f.admin.update("DELETE FROM commerce.payment_transaction WHERE attempt_id IN(SELECT a.id FROM commerce.payment_attempt a JOIN commerce.sales_order o ON o.id=a.order_id WHERE o.market_id=?)",f.market);f.admin.update("DELETE FROM commerce.payment_attempt WHERE order_id IN(SELECT id FROM commerce.sales_order WHERE market_id=?)",f.market);f.admin.update("DELETE FROM commerce.sales_order WHERE market_id=?",f.market);f.admin.update("DELETE FROM commerce.affiliate_bank_detail WHERE party_id=?",f.customer.party());f.admin.update("DELETE FROM commerce.idempotency_record WHERE principal_key=? AND operation IN ('API-230','API-231','API-232','API-233')",finance.party().toString());}finally{f.admin.execute("ALTER TABLE commerce.affiliate_payout ENABLE TRIGGER USER");f.admin.execute("ALTER TABLE commerce.affiliate_bank_detail ENABLE TRIGGER USER");}});}
 }
 @Test void bankNumbersAreEncryptedMaskedAndIdempotentAndChangesResetReview(){rollback(()->{String command=key();var first=service.saveBank(f.customer,bankInput(null,"0123456789"),command,correlation());assertThat(first.bank().accountNumber()).isNull();assertThat(first.bank().accountLast4()).isEqualTo("6789");assertThat(service.saveBank(f.customer,bankInput(null,"0123456789"),command,correlation()).bank().id()).isEqualTo(first.bank().id());assertThatThrownBy(()->service.saveBank(f.customer,bankInput(null,"9999999999"),command,correlation())).hasMessage("IDEMPOTENCY_HASH_MISMATCH");var row=f.jdbc.queryForMap("SELECT * FROM commerce.affiliate_bank_detail WHERE id=?",first.bank().id());assertThat(new String((byte[])row.get("payload_ciphertext"),java.nio.charset.StandardCharsets.US_ASCII)).doesNotContain("0123456789");assertThatThrownBy(()->secrets.open(first.bank().id(),f.finance.party(),(byte[])row.get("payload_ciphertext"),(String)row.get("content_hash"),"MOCK")).hasMessage("PAYMENT_RECEIPT_CIPHER_REJECTED");service.review(finance,f.customer.party(),EventCodec.JSON.valueToTree(Map.of("bankId",first.bank().id(),"version",0,"decision","APPROVED","reason","Synthetic approval")),key(),correlation());assertThat(service.detail(finance,f.customer.party(),0,correlation()).bank().accountNumber()).isEqualTo("0123456789");var updated=service.saveBank(f.customer,bankInput(first.bank().id(),"0123456789"),key(),correlation());assertThat(updated.bank().revision()).isEqualTo(2);assertThat(updated.bank().status()).isEqualTo("PENDING");assertThatThrownBy(()->service.saveBank(f.customer,bankInput(first.bank().id(),"0123456789"),key(),correlation())).hasMessage("VERSION_MISMATCH");});}
 @Test void currentFinanceWithoutMfaCanReviewButSalesAndRevokedRolesCannot(){rollback(()->{assertThat(finance.mfaAt()).isNull();approved();assertThat(service.list(finance,0).items()).hasSize(1);assertThatThrownBy(()->service.list(f.sales,0)).hasMessage("ACCESS_DENIED");f.jdbc.update("UPDATE commerce.staff_role_assignment SET revoked_at=now() WHERE party_id=? AND role='FINANCE'",finance.party());assertThatThrownBy(()->service.list(finance,0)).hasMessage("ACCESS_DENIED");});}
 @Test void preparedBalanceIsReservedAndBankCannotChangeAndPaidReplayDoesNotPayTwice(){rollback(()->{var bank=approved();credit("45.00");String command=key();var input=EventCodec.JSON.valueToTree(Map.of("bankId",bank.id()));var payout=service.prepare(finance,f.customer.party(),input,command,correlation());assertThat(payout.amount()).isEqualTo("45.00");assertThat(service.prepare(finance,f.customer.party(),input,command,correlation()).id()).isEqualTo(payout.id());assertThatThrownBy(()->service.prepare(finance,f.customer.party(),input,key(),correlation())).hasMessage("CONFLICT");var account=service.own(f.customer,0);assertThat(account.balance().available()).isEqualTo("0.00");assertThat(account.balance().reserved()).isEqualTo("45.00");assertThat(account.canTransfer()).isTrue();assertThatThrownBy(()->service.saveBank(f.customer,bankInput(bank.id(),"1234567890"),key(),correlation())).hasMessage("CONFLICT");String paidKey=key();var paid=service.resolve(finance,payout.id(),true,resolved(payout,true,"SYNTHETIC_TRANSFER_1"),paidKey,correlation());assertThat(paid.state()).isEqualTo("PAID");assertThat(service.resolve(finance,payout.id(),true,resolved(payout,true,"SYNTHETIC_TRANSFER_1"),paidKey,correlation()).state()).isEqualTo("PAID");assertThat(service.prepare(finance,f.customer.party(),input,command,correlation()).state()).isEqualTo("PAID");credit("45.00");assertThat(service.own(f.customer,0).balance().available()).isEqualTo("45.00");assertThatThrownBy(()->service.prepare(finance,f.customer.party(),input,key(),correlation())).hasMessage("CONFLICT");assertThat(service.own(f.customer,0).balance().paid()).isEqualTo("45.00");});}
 @Test void cancellationRequiresNoTransferConfirmationAndReleasesReservation(){rollback(()->{var bank=approved();credit("45.00");var payout=service.prepare(finance,f.customer.party(),EventCodec.JSON.valueToTree(Map.of("bankId",bank.id())),key(),correlation());assertThatThrownBy(()->service.resolve(finance,payout.id(),false,EventCodec.JSON.valueToTree(Map.of("version",0,"reason","Synthetic cancellation","confirmNoTransfer",false)),key(),correlation())).hasMessage("VALIDATION_ERROR");service.resolve(finance,payout.id(),false,resolved(payout,false,"Synthetic no transfer"),key(),correlation());assertThat(service.own(f.customer,0).balance().reserved()).isEqualTo("0.00");assertThat(service.own(f.customer,0).balance().available()).isEqualTo("45.00");assertThat(service.own(f.customer,0).canPrepare()).isTrue();});}
 @Test void postPaidRefundIsRecoveredFromFutureEarningsAndDuplicateTransferReferenceRejected(){rollback(()->{var bank=approved();Credit credit=credit("45.00");var payout=service.prepare(finance,f.customer.party(),EventCodec.JSON.valueToTree(Map.of("bankId",bank.id())),key(),correlation());service.resolve(finance,payout.id(),true,resolved(payout,true,"SYNTHETIC_REFUND_RECOVERY"),key(),correlation());UUID refund=UUID.randomUUID();f.jdbc.update("INSERT INTO commerce.refund(id,created_by,updated_by,order_id,attempt_id,request_key,amount,currency_code,state,reason,requested_by,provider_reference) VALUES (?,'test','test',?,?,?,?,'NGN','SUCCEEDED','Synthetic full refund',?,?)",refund,credit.order(),credit.attempt(),key(),credit.basis(),finance.party(),"synthetic-"+refund);f.jdbc.update("INSERT INTO commerce.refund_line(id,created_by,updated_by,refund_id,order_line_id,quantity,amount) VALUES (?,'test','test',?,?,1,?)",UUID.randomUUID(),refund,credit.line(),credit.basis());commissions.refundSettled(refund,correlation());assertThat(service.own(f.customer,0).balance().recovery()).isEqualTo("45.00");clock.value=Instant.parse("2026-12-20T00:00:00Z");credit("30.00");assertThat(service.own(f.customer,0).balance().recovery()).isEqualTo("15.00");credit("20.00");assertThat(service.own(f.customer,0).balance().available()).isEqualTo("5.00");var next=service.prepare(finance,f.customer.party(),EventCodec.JSON.valueToTree(Map.of("bankId",bank.id())),key(),correlation());assertThat(next.amount()).isEqualTo("5.00");assertThatThrownBy(()->service.resolve(finance,next.id(),true,resolved(next,true,"SYNTHETIC_REFUND_RECOVERY"),key(),correlation())).hasMessage("CONFLICT");});}
}
